package hu.bankmonitor.payments.transfers;

import hu.bankmonitor.payments.accounts.AccountLocking;
import hu.bankmonitor.payments.accounts.LockedAccounts;
import hu.bankmonitor.payments.common.Money;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Requests a Transfer: funds reserved on the source Account, nothing moved, and a {@code
 * PENDING} Transfer to hold the request while its Checks are outstanding.
 *
 * <p><b>The order inside {@link #reserve} is the correctness argument</b>, and it is the
 * reason the three statements are not interchangeable:
 *
 * <ol>
 * <li>lock both Accounts, ascending by ID, which {@link AccountLocking} owns;
 * <li><em>then</em> read the source Account's Available Balance and test the amount against
 * it;
 * <li>write the reservation and the Transfer.
 * </ol>
 *
 * <p>Because the check follows the lock, the figure it tests against cannot be invalidated
 * between reading it and acting on it: any other transaction that would spend the same
 * Available Balance is waiting on the row until this one commits, and then reads what this
 * one wrote. Checking first and locking second would compile, pass every single-threaded
 * test, and overdraw under load.
 *
 * <p>Nothing here saves the source Account, and that is not an omission. The Accounts come
 * back from {@link AccountLocking} attached to this transaction's persistence context, so
 * raising the Reserved Amount <em>is</em> the write, flushed on commit alongside the
 * Transfer. There is no other way for this slice to do it either: design decision 30 keeps
 * {@code AccountRepository} package-private, and locking is the whole of what {@code
 * accounts} exports.
 *
 * <p>The Exchange Rate is deliberately not fetched here. Design decision 4 puts it in a
 * phase of its own with no transaction open and no locks held, which is what makes
 * pessimistic locking affordable at all; {@code LockedPathTouchesOnlyTheDatabaseTest} names
 * this class and fails if anything it can reach would wait on a provider.
 */
@Service
class FundsReservation {

	private final AccountLocking accounts;

	private final TransferRepository transfers;

	FundsReservation(AccountLocking accounts, TransferRepository transfers) {
		this.accounts = accounts;
		this.transfers = transfers;
	}

	/**
	 * Reserves the amount on the source Account and records the {@code PENDING} Transfer it
	 * is held for, in one transaction that writes both or neither.
	 *
	 * <p>The transaction is opened here rather than inherited, which is what {@link
	 * AccountLocking}'s mandatory propagation is checking for. Ticket 16 will widen it to
	 * carry the idempotency record's flip to {@code SUCCEEDED} in the same commit, per
	 * design decision 4.
	 *
	 * @throws hu.bankmonitor.payments.accounts.UnknownAccountException  if either Account ID
	 *                                                                  has no row
	 * @throws hu.bankmonitor.payments.accounts.InsufficientFundsException if the source
	 *                                                                  Account's Available
	 *                                                                  Balance does not
	 *                                                                  cover the amount
	 * @throws CrossCurrencyTransferNotSupportedException if the two Accounts are denominated
	 *                                                    differently
	 * @throws IllegalArgumentException if both IDs name the same Account
	 */
	@Transactional
	public Transfer reserve(ReservationRequest request) {
		LockedAccounts locked =
				accounts.lockForTransfer(request.sourceAccountId(), request.destinationAccountId());
		Money amount = denominate(request.amountMinorUnits(), locked);

		locked.source().reserve(amount);

		return transfers.save(new Transfer(request.sourceAccountId(), request.destinationAccountId(),
				amount, amount, request.requestedAt()));
	}

	/**
	 * The requested count of Minor Units, denominated by the Accounts it moves between.
	 *
	 * <p>Same-Currency Transfers only, so the one figure is both the debited and the
	 * credited amount — the conversion happened, at a rate of one. Ticket 26 is where the
	 * two part company.
	 */
	private static Money denominate(long amountMinorUnits, LockedAccounts locked) {
		if (locked.source().getCurrency() != locked.destination().getCurrency()) {
			throw new CrossCurrencyTransferNotSupportedException(
					locked.source().getCurrency(), locked.destination().getCurrency());
		}
		return new Money(amountMinorUnits, locked.source().getCurrency());
	}
}
===== transfers/ReservationRequest.java =====
package hu.bankmonitor.payments.transfers;

import java.time.Instant;
import java.util.Objects;

/**
 * What a caller has to say to request a Transfer: the two Accounts, how much to move, and
 * when it was asked for.
 *
 * <p><b>The amount is a bare count of Minor Units and not {@link
 * hu.bankmonitor.payments.common.Money}</b>, which is the one place in this context where a
 * number without a Currency is the honest shape. The Currency of a Transfer is the source
 * Account's, and the source Account is only read under the row lock design decision 6
 * requires — so a caller could only name a Currency here by reading the Account first,
 * outside the lock, which is the read that design decision exists to forbid. The count
 * becomes Money inside {@link FundsReservation}, at the first moment there is an Account to
 * denominate it.
 *
 * <p>Design decision 15 locks the Exchange Rate at request time, so ticket 26 will bring a
 * second amount for the credited side. Until then both sides of a Transfer are the same
 * figure and this carries it once.
 */
public record ReservationRequest(
		long sourceAccountId,
		long destinationAccountId,
		long amountMinorUnits,
		Instant requestedAt) {

	public ReservationRequest {
		Objects.requireNonNull(requestedAt, "a transfer is requested at a time");
	}
}
===== transfers/CrossCurrencyTransferNotSupportedException.java =====
package hu.bankmonitor.payments.transfers;

import hu.bankmonitor.payments.common.Currency;

/**
 * Raised when the two Accounts of a Transfer are denominated differently, which this build
 * cannot yet answer.
 *
 * <p>A temporary refusal, and named after the limitation rather than after a rule, so that
 * ticket 26 deletes it rather than reinterpreting it. What it stands in for is design
 * decision 15's conversion: the credited amount has to be the debited amount at a quoted
 * Exchange Rate, and until there is one, a Transfer between two Currencies has no second
 * figure to write. Reserving anyway would put the source Account's Currency into the
 * destination's column and leave a row that settles into the wrong money.
 *
 * <p>Decided under the lock rather than before it, because the two Currencies are properties
 * of the two rows, and reading a row outside the lock is what design decision 6 forbids.
 */
public class CrossCurrencyTransferNotSupportedException extends RuntimeException {

	private final Currency sourceCurrency;

	private final Currency destinationCurrency;

	public CrossCurrencyTransferNotSupportedException(Currency sourceCurrency, Currency destinationCurrency) {
		super("transfers from %s to %s need an exchange rate, which this build does not yet fetch"
				.formatted(sourceCurrency, destinationCurrency));
		this.sourceCurrency = sourceCurrency;
		this.destinationCurrency = destinationCurrency;
	}

	public Currency getSourceCurrency() {
		return sourceCurrency;
	}

	public Currency getDestinationCurrency() {
		return destinationCurrency;
	}
}
===== accounts/InsufficientFundsException.java =====
package hu.bankmonitor.payments.accounts;

import hu.bankmonitor.payments.common.Money;

/**
 * Raised when a Transfer asks an Account to reserve more than its Available Balance.
 *
 * <p>Carries both figures because the useful answer to "why was this refused" is the two
 * amounts that were compared, and neither is recoverable from the Account afterwards — by
 * the time a caller reads it the transaction that refused has rolled back. It carries no
 * Account ID, unlike {@link UnknownAccountException}: a Transfer has two Accounts but only
 * one it debits, so there is nothing to disambiguate.
 *
 * <p>Whether the client is told {@code 409} or {@code 422}, and under which problem type
 * URN, belongs to the endpoint in ticket 14.
 */
public class InsufficientFundsException extends RuntimeException {

	private final Money availableBalance;

	private final Money requestedAmount;

	public InsufficientFundsException(Money availableBalance, Money requestedAmount) {
		super("available balance %s does not cover %s".formatted(availableBalance, requestedAmount));
		this.availableBalance = availableBalance;
		this.requestedAmount = requestedAmount;
	}

	/** What the Account could still spend when the reservation was refused. */
	public Money getAvailableBalance() {
		return availableBalance;
	}

	/** What the Transfer asked to reserve. */
	public Money getRequestedAmount() {
		return requestedAmount;
	}
}

