===== ReservationScenario.java =====
package hu.bankmonitor.payments.transfers;

import hu.bankmonitor.payments.common.Currency;
import hu.bankmonitor.testsupport.BootedApplicationTest;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;

import java.time.Instant;
import java.util.List;
import java.util.Map;

/**
 * The Accounts, the reads and the cleanup the two reservation tests share.
 *
 * <p><b>Nothing here is transactional, and that is the point.</b> A {@code @Transactional}
 * test method makes every write it performs invisible to any other connection and rolls the
 * lot back at the end — which would leave
 * {@link ConcurrentReservationsHoldTheBalanceTest}'s second thread unable to see the first
 * thread's reservation, and every assertion in
 * {@link ReservedFundsReachTheTableTest} agreeing with a transaction that never committed.
 * Both classes need real commits, so the price is paying for the cleanup by hand.
 *
 * <p>The tables are emptied before each method as well as after: the context this extends is
 * shared with the {@code accounts} tests, which write to the same H2 database, and the
 * assertions below count rows rather than looking only at their own.
 *
 * <p>Rows go in and come back out in SQL rather than through the entities, so what is
 * asserted is what reached the database — a round trip through the mapping under test would
 * agree with itself whatever it wrote.
 */
abstract class ReservationScenario extends BootedApplicationTest {

	static final Instant REQUESTED_AT = Instant.parse("2026-09-05T10:15:30Z");

	@Autowired
	FundsReservation reservation;

	@Autowired
	private JdbcTemplate database;

	@BeforeEach
	@AfterEach
	void emptyTheTransferAndAccountTables() {
		database.update("DELETE FROM transfers");
		database.update("DELETE FROM accounts");
	}

	/**
	 * With an explicit identifier, which the identity column accepts because it is declared
	 * {@code generated by default}. The lock order is ascending by ID, so a test about two
	 * Accounts needs to be able to say which of them is the lower one.
	 */
	void openAccount(long id, long balanceMinorUnits, Currency currency) {
		database.update("""
				INSERT INTO accounts (id, balance_minor_units, balance_currency,
				                      reserved_amount_minor_units, reserved_amount_currency)
				VALUES (?, ?, ?, 0, ?)
				""", id, balanceMinorUnits, currency.name(), currency.name());
	}

	static ReservationRequest transferOf(long amountMinorUnits, long sourceAccountId, long destinationAccountId) {
		return new ReservationRequest(sourceAccountId, destinationAccountId, amountMinorUnits, REQUESTED_AT);
	}

	long balanceOf(long accountId) {
		return minorUnitsOf("balance_minor_units", accountId);
	}

	long reservedAmountOf(long accountId) {
		return minorUnitsOf("reserved_amount_minor_units", accountId);
	}

	/** What an overdraft check tests against, read back from the two columns it is derived from. */
	long availableBalanceOf(long accountId) {
		return balanceOf(accountId) - reservedAmountOf(accountId);
	}

	List<Map<String, Object>> transferRows() {
		return database.queryForList("SELECT * FROM transfers ORDER BY id");
	}

	private long minorUnitsOf(String column, long accountId) {
		Long minorUnits = database.queryForObject(
				"SELECT " + column + " FROM accounts WHERE id = ?", Long.class, accountId);
		return minorUnits == null ? 0L : minorUnits;
	}
}
===== ReservedFundsReachTheTableTest.java =====
package hu.bankmonitor.payments.transfers;

import hu.bankmonitor.payments.accounts.InsufficientFundsException;
import hu.bankmonitor.payments.accounts.UnknownAccountException;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static hu.bankmonitor.payments.common.Currency.EUR;
import static hu.bankmonitor.payments.common.Currency.HUF;
import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.assertj.core.api.InstanceOfAssertFactories.type;

/**
 * What one reservation leaves behind: a raised Reserved Amount, a {@code PENDING} Transfer,
 * and no money anywhere else.
 *
 * <p>These are the single-threaded halves of the claim.
 * {@link ConcurrentReservationsHoldTheBalanceTest} is where two threads make the ordering of
 * the lock and the balance check matter; here what is being asserted is that the operation
 * writes what it says it writes, and — the more easily lost half — that a refused one writes
 * nothing at all. A reservation and a Transfer that could commit separately would leave funds
 * held against a request that does not exist, so every refusal below reads the tables back to
 * show that neither happened.
 */
class ReservedFundsReachTheTableTest extends ReservationScenario {

	private static final long SOURCE = 1L;
	private static final long DESTINATION = 2L;
	private static final long OPENING_BALANCE = 250_00L;

	@BeforeEach
	void openBothAccounts() {
		openAccount(SOURCE, OPENING_BALANCE, EUR);
		openAccount(DESTINATION, 0L, EUR);
	}

	@Test
	@DisplayName("reserving raises the source Account's Reserved Amount and moves no money")
	void raisesTheReservedAmountAndMovesNoMoney() {
		Transfer requested = reservation.reserve(transferOf(80_00L, SOURCE, DESTINATION));

		assertThat(requested.getId()).isNotNull();
		assertThat(requested.getStatus()).isEqualTo(TransferStatus.PENDING);

		assertThat(balanceOf(SOURCE)).isEqualTo(OPENING_BALANCE);
		assertThat(reservedAmountOf(SOURCE)).isEqualTo(80_00L);
		assertThat(availableBalanceOf(SOURCE)).isEqualTo(170_00L);

		assertThat(balanceOf(DESTINATION)).isZero();
		assertThat(reservedAmountOf(DESTINATION)).isZero();
	}

	/**
	 * A same-Currency Transfer carries the same figure twice, denominated by the source
	 * Account rather than by anything the caller said: {@link ReservationRequest} has only a
	 * count of Minor Units to offer.
	 */
	@Test
	@DisplayName("the PENDING Transfer records both amounts in the Accounts' Currency")
	void recordsThePendingTransferInTheAccountsCurrency() {
		reservation.reserve(transferOf(80_00L, SOURCE, DESTINATION));

		assertThat(transferRows()).singleElement().satisfies(row -> assertThat(row)
				.containsEntry("STATUS", "PENDING")
				.containsEntry("SOURCE_ACCOUNT_ID", SOURCE)
				.containsEntry("DESTINATION_ACCOUNT_ID", DESTINATION)
				.containsEntry("DEBITED_AMOUNT_MINOR_UNITS", 80_00L)
				.containsEntry("DEBITED_AMOUNT_CURRENCY", "EUR")
				.containsEntry("CREDITED_AMOUNT_MINOR_UNITS", 80_00L)
				.containsEntry("CREDITED_AMOUNT_CURRENCY", "EUR"));
	}

