1	package hu.bankmonitor.testsupport;
2	
3	import org.hibernate.cfg.AvailableSettings;
4	import org.hibernate.resource.jdbc.spi.StatementInspector;
5	import org.springframework.boot.hibernate.autoconfigure.HibernatePropertiesCustomizer;
6	
7	import java.time.Duration;
8	import java.util.Map;
9	import java.util.concurrent.CountDownLatch;
10	import java.util.concurrent.TimeUnit;
11	import java.util.concurrent.atomic.AtomicReference;
12	
13	/**
14	 * Holds each thread at the first row lock it asks for until an expected number of threads
15	 * have asked, so that a test can arrange for several transactions to be holding one lock
16	 * each at the moment any of them reaches for a second.
17	 *
18	 * <p><b>Why a test needs this at all.</b> A latch that releases two threads at the start of
19	 * an operation lines up their <em>beginnings</em>, and nothing else. Against an in-memory
20	 * database the whole of a reservation — two locks, an update and an insert — runs in well
21	 * under the time it takes to schedule the second thread, so the first transaction routinely
22	 * commits before the second acquires anything, and a design that took its locks in an order
23	 * that can deadlock passes anyway. That is the shape of green test the reservation tickets
24	 * were warned about: it exercises the code twice rather than concurrently.
25	 *
26	 * <p>Interleaving that is decidable has to be forced at the only point where the ordering is
27	 * observable, which is the lock acquisition itself. Hibernate's {@link StatementInspector}
28	 * sees every statement before it is sent, and a {@code select … for update} is a lock
29	 * acquisition about to happen, so a barrier here is exactly a barrier between one
30	 * transaction's first lock and its second.
31	 *
32	 * <p>It is <em>only</em> a test hook: nothing in {@code src/main} knows this exists, and it
33	 * is inert until {@link #holdEachThreadAtItsFirstRowLock} arms it. That is what makes it a
34	 * fair trade where a hook compiled into the production path would not have been.
35	 *
36	 * <p>Register it with {@code @Import(RowLockBarrier.class)} on the test class that needs it.
37	 * Doing so gives that class an application context of its own rather than the one
38	 * {@link BootedApplicationTest} shares, which costs one extra boot — the price of a
39	 * concurrency claim that can fail.
40	 */
41	public final class RowLockBarrier implements StatementInspector, HibernatePropertiesCustomizer {
42	
43		/** Reached only when a thread the barrier is waiting for never arrives, which is a failure. */
44		private static final Duration BEFORE_GIVING_UP = Duration.ofSeconds(10);
45	
46		private final AtomicReference<CountDownLatch> everyThreadsFirstRowLock = new AtomicReference<>();
47	
48		private final ThreadLocal<Boolean> alreadyHolding = ThreadLocal.withInitial(() -> false);
49	
50		@Override
51		public void customize(Map<String, Object> hibernateProperties) {
52			hibernateProperties.put(AvailableSettings.STATEMENT_INSPECTOR, this);
53		}
54	
55		/**
56		 * Arms the barrier for one race: the next {@code threads} threads to ask for a row lock
57		 * are held until all of them have asked, and then released together.
58		 *
59		 * <p>Per thread rather than per statement — a thread already past the barrier runs
60		 * unimpeded, which is what leaves it free to reach for its second lock and find out
61		 * whether another thread is sitting on it.
62		 */
63		public void holdEachThreadAtItsFirstRowLock(int threads) {
64			everyThreadsFirstRowLock.set(new CountDownLatch(threads));
65		}
66	
67		/** Disarms the barrier, releasing anything still waiting on it. */
68		public void release() {
69			CountDownLatch arrivals = everyThreadsFirstRowLock.getAndSet(null);
70			if (arrivals != null) {
71				while (arrivals.getCount() > 0) {
72					arrivals.countDown();
73				}
74			}
75		}
76	
77		@Override
78		public String inspect(String sql) {
79			CountDownLatch arrivals = everyThreadsFirstRowLock.get();
80			if (arrivals != null && isARowLock(sql) && !alreadyHolding.get()) {
81				alreadyHolding.set(true);
82				arrivals.countDown();
83				awaitTheOthers(arrivals);
84			}
85			System.err.println("INSPECT[" + (everyThreadsFirstRowLock.get() != null) + "] " + sql);
86			return sql;
87		}
88	
89		private static boolean isARowLock(String sql) {
90			return sql.toLowerCase().contains("for update");
91		}
92	
93		private static void awaitTheOthers(CountDownLatch arrivals) {
94			try {
95				arrivals.await(BEFORE_GIVING_UP.toSeconds(), TimeUnit.SECONDS);
96			}
97			catch (InterruptedException interrupted) {
98				Thread.currentThread().interrupt();
99			}
100		}
101	}

