package hu.bankmonitor.payments.transfers;

import hu.bankmonitor.payments.common.Currency;
import hu.bankmonitor.testsupport.BootedApplicationTest;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;

import java.time.Instant;
import java.util.List;
import java.util.Map;

/**
 * The Accounts, the reads and the cleanup the two reservation tests share.
 *
 * <p><b>Nothing here is transactional, and that is the point.</b> A {@code @Transactional}
 * test method makes every write it performs invisible to any other connection and rolls the
 * lot back at the end — which would leave
 * {@link ConcurrentReservationsHoldTheBalanceTest}'s second thread unable to see the first
 * thread's reservation, and every assertion in
 * {@link ReservedFundsReachTheTableTest} agreeing with a transaction that never committed.
 * Both classes need real commits, so the price is paying for the cleanup by hand.
 *
 * <p>The tables are emptied before each method as well as after: the context this extends is
 * shared with the {@code accounts} tests, which write to the same H2 database, and the
 * assertions below count rows rather than looking only at their own.
 *
 * <p>Rows go in and come back out in SQL rather than through the entities, so what is
 * asserted is what reached the database — a round trip through the mapping under test would
 * agree with itself whatever it wrote.
 */
abstract class ReservationScenario extends BootedApplicationTest {

	static final Instant REQUESTED_AT = Instant.parse("2026-09-05T10:15:30Z");

	@Autowired
	FundsReservation reservation;

	@Autowired
	private JdbcTemplate database;

	@BeforeEach
	@AfterEach
	void emptyTheTransferAndAccountTables() {
		database.update("DELETE FROM transfers");
		database.update("DELETE FROM accounts");
	}

	/**
	 * With an explicit identifier, which the identity column accepts because it is declared
	 * {@code generated by default}. The lock order is ascending by ID, so a test about two
	 * Accounts needs to be able to say which of them is the lower one.
	 */
	void openAccount(long id, long balanceMinorUnits, Currency currency) {
		database.update("""
				INSERT INTO accounts (id, balance_minor_units, balance_currency,
				                      reserved_amount_minor_units, reserved_amount_currency)
				VALUES (?, ?, ?, 0, ?)
				""", id, balanceMinorUnits, currency.name(), currency.name());
	}

	static ReservationRequest transferOf(long amountMinorUnits, long sourceAccountId, long destinationAccountId) {
		return new ReservationRequest(sourceAccountId, destinationAccountId, amountMinorUnits, REQUESTED_AT);
	}

	long balanceOf(long accountId) {
		return minorUnitsOf("balance_minor_units", accountId);
	}

	long reservedAmountOf(long accountId) {
		return minorUnitsOf("reserved_amount_minor_units", accountId);
	}

	/** What an overdraft check tests against, read back from the two columns it is derived from. */
	long availableBalanceOf(long accountId) {
		return balanceOf(accountId) - reservedAmountOf(accountId);
	}

	List<Map<String, Object>> transferRows() {
		return database.queryForList("SELECT * FROM transfers ORDER BY id");
	}

	private long minorUnitsOf(String column, long accountId) {
		Long minorUnits = database.queryForObject(
				"SELECT " + column + " FROM accounts WHERE id = ?", Long.class, accountId);
		return minorUnits == null ? 0L : minorUnits;
	}
}

package hu.bankmonitor.payments.accounts;

import hu.bankmonitor.payments.common.Currency;
import hu.bankmonitor.payments.common.Money;
import jakarta.persistence.AttributeOverride;
import jakarta.persistence.Column;
import jakarta.persistence.Embedded;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

import java.util.Objects;

/**
 * A balance held in one currency, and the part of it already committed to transfers that
 * have not finished.
 *
 * <p>The atomic entity of this context: nothing owns an Account. {@code User} is named in
 * {@code CONTEXT.md} as deliberately unmodelled, and design decision 1 has why.
 *
 * <p><b>Two figures rather than one</b>, per design decision 13. The balance is what the
 * Account holds; the Reserved Amount is what is spoken for. Their difference is the
 * {@linkplain #getAvailableBalance() Available Balance}, which is what an overdraft check
 * tests against — so an Account's own row answers "how much of this is still spendable"
 * without reading a single transfer. Reserving raises the Reserved Amount, settling lowers
 * both, and rejection or expiry lowers only the Reserved Amount.
 *
 * <p>The currency is fixed at creation and there is no way to change it: an Account that
 * could be redenominated would make every historical balance ambiguous. Both figures carry
 * it because both are {@link Money}, and {@link #getCurrency()} is the single answer they
 * are constructed to agree on.
 */
@Entity
@Table(name = "accounts")
public class Account {

	@Id
	@GeneratedValue(strategy = GenerationType.IDENTITY)
	private Long id;

	@Embedded
	@AttributeOverride(name = "minorUnits", column = @Column(name = "balance_minor_units"))
	@AttributeOverride(name = "currency", column = @Column(name = "balance_currency"))
	private Money balance;

	@Embedded
	@AttributeOverride(name = "minorUnits", column = @Column(name = "reserved_amount_minor_units"))
	@AttributeOverride(name = "currency", column = @Column(name = "reserved_amount_currency"))
	private Money reservedAmount;

	protected Account() {
		// required by JPA
	}

	/**
	 * Opens an Account holding the given amount, with nothing reserved against it. The
	 * opening balance carries the currency, so there is no way to name one that disagrees
	 * with the other figure.
	 */
	public Account(Money openingBalance) {
		this.balance = Objects.requireNonNull(openingBalance, "an account opens with a balance");
		this.reservedAmount = Money.zero(openingBalance.currency());
	}

	public Long getId() {
		return id;
	}

	/** Everything the Account holds, including the part already spoken for. */
	public Money getBalance() {
		return balance;
	}

	/** The part of the balance committed to transfers that have not reached a terminal state. */
	public Money getReservedAmount() {
		return reservedAmount;
	}

	/** What the Account can still spend, and the figure an overdraft check tests against. */
	public Money getAvailableBalance() {
		return balance.minus(reservedAmount);
	}

	/** Fixed when the Account was opened. Both figures are denominated in it. */
	public Currency getCurrency() {
		return balance.currency();
	}

	/**
	 * Commits part of the Available Balance to a Transfer that has not settled: the Reserved
	 * Amount rises by the amount, the balance does not move, and nothing is credited
	 * anywhere. Settling the Transfer lowers both figures; rejecting or expiring it lowers
	 * only the Reserved Amount.
	 *
	 * <p>The refusal lives here rather than in the caller so that there is no way to reach a
	 * balance and overdraw it — but <em>whether it is safe to have asked</em> does not. This
	 * method compares two figures it was handed; that the Account's row is locked while it
	 * does so is the caller's obligation, and design decision 6 is why. Called against an
	 * unlocked Account the arithmetic is still right and the answer is still worthless,
	 * because another transaction may have spent the same Available Balance in between.
	 *
	 * @throws InsufficientFundsException if the Available Balance does not cover the amount
	 * @throws IllegalArgumentException   if the amount is in another Currency
	 */
	public void reserve(Money amount) {
		Money availableBalance = getAvailableBalance();
		if (availableBalance.isLessThan(amount)) {
			throw new InsufficientFundsException(availableBalance, amount);
		}
		reservedAmount = reservedAmount.plus(amount);
	}
}

package hu.bankmonitor.payments.transfers;

import hu.bankmonitor.payments.accounts.InsufficientFundsException;
import hu.bankmonitor.testsupport.RowLockBarrier;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Import;

import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.stream.Stream;

import static hu.bankmonitor.payments.common.Currency.EUR;
import static org.assertj.core.api.Assertions.assertThat;

/**
 * The two threads design decision 6 exists for: one Available Balance that cannot be spent
 * twice, and two Transfers in opposite directions that cannot wait on each other.
 *
 * <p>These are the tests the design's central integrity claim rests on, and both of them are
 * easy to write in a shape that proves nothing. Three traps, avoided deliberately:
 *
 * <ul>
 * <li><b>A transactional test method.</b> {@link ReservationScenario} is not annotated
 * {@code @Transactional}, so each thread's reservation really commits. Wrapped in one
 * transaction instead, the second thread would be looking at a connection that cannot see
 * the first thread's uncommitted work, and the race would be invisible rather than absent.
 * The price is emptying the tables by hand, which that class pays.
 * <li><b>Threads that never overlap.</b> Submitting two tasks does not make them concurrent:
 * on an in-memory database the first finishes in well under the time it takes to schedule the
 * second, and the second then reads a settled world.
 * <li><b>A latch in the wrong place.</b> Releasing both threads at the <em>start</em> of the
 * operation is not enough, and this was measured rather than assumed: with a start latch and
 * nothing else, {@link #opposingTransfersBetweenOnePairOfAccountsBothComplete} stayed green
 * after the ascending-ID rule was deleted from {@code AccountLocking}, because thread one
 * still committed before thread two acquired anything. The ordering only becomes observable
 * at the lock acquisitions themselves, so that is where {@link RowLockBarrier} holds the two
 * threads: each is stopped at its first {@code select … for update} until both have got
 * there, and only then are they let go to reach for their second.
 * </ul>
 *
 * <p>With the barrier in place both claims below are falsifiable, which is the only reason
 * to believe them: dropping {@code @Lock(PESSIMISTIC_WRITE)} fails
 * {@link #exactlyOneOfTwoConcurrentTransfersOutOfOneAccountSucceeds}, and locking by role
 * instead of by ascending ID fails
 * {@link #opposingTransfersBetweenOnePairOfAccountsBothComplete}.
 *
 * <p>Both tests run on H2, whose lock timeout is around a second where Postgres waits
 * indefinitely. Nothing here holds a lock for anything like that long — the whole transaction
 * is four statements against an in-memory table — but {@code docs/deferred.md} names running
 * this suite against Postgres as a production prerequisite rather than a nicety, and this is
 * the suite it means.
 */
@Import(RowLockBarrier.class)
class ConcurrentReservationsHoldTheBalanceTest extends ReservationScenario {

	private static final long LOWER_ID = 1L;
	private static final long HIGHER_ID = 2L;

	/** Generous, because it is only ever reached by a deadlock, and then the test has failed. */
	private static final Duration BEFORE_GIVING_UP = Duration.ofSeconds(10);

	@Autowired
	private RowLockBarrier rowLocks;

	/**
	 * Two Transfers of 150.00 against an Available Balance of 200.00: either alone is
	 * covered, and the two together are not, so "both succeeded" is a distinguishable
	 * outcome rather than an arithmetic coincidence.
	 */
	@Test
	@DisplayName("two concurrent Transfers out of one Account: exactly one succeeds")
	void exactlyOneOfTwoConcurrentTransfersOutOfOneAccountSucceeds() throws Exception {
		openAccount(LOWER_ID, 200_00L, EUR);
		openAccount(HIGHER_ID, 0L, EUR);

		List<Attempt> attempts = race(
				transferOf(150_00L, LOWER_ID, HIGHER_ID),
				transferOf(150_00L, LOWER_ID, HIGHER_ID));

		assertThat(attempts).filteredOn(Attempt::succeeded).hasSize(1);
		assertThat(attempts).filteredOn(attempt -> !attempt.succeeded())
				.singleElement()
				.extracting(Attempt::refusal)
				.isInstanceOf(InsufficientFundsException.class);

		assertThat(transferRows()).singleElement()
				.satisfies(row -> assertThat(row).containsEntry("STATUS", "PENDING"));
	}

	/**
	 * The claim the previous test's arithmetic is in aid of: whatever the two threads did,
	 * the Account did not end up owing money it does not hold. The table's own
	 * {@code ACCOUNTS_RESERVED_WITHIN_BALANCE} constraint would have refused the write, so a
	 * failure here is a failure of the design rather than of the check.
	 */
	@Test
	@DisplayName("the Account never reserves more than it holds, however the race went")
	void neverReservesMoreThanTheAccountHolds() throws Exception {
		openAccount(LOWER_ID, 200_00L, EUR);
		openAccount(HIGHER_ID, 0L, EUR);

		race(transferOf(150_00L, LOWER_ID, HIGHER_ID), transferOf(150_00L, LOWER_ID, HIGHER_ID));

		assertThat(balanceOf(LOWER_ID)).isEqualTo(200_00L);
		assertThat(reservedAmountOf(LOWER_ID)).isEqualTo(150_00L);
		assertThat(availableBalanceOf(LOWER_ID)).isNotNegative().isEqualTo(50_00L);
	}

	/**
	 * The demonstration the ascending-ID rule exists for, and the reason
	 * {@link RowLockBarrier} is worth its weight. Held at their first lock until both have
	 * asked for one, two role-ordered Transfers would each be holding what the other wants:
	 * one thread on the lower Account waiting for the higher, the other the reverse. Ordered
	 * by ID, both ask for the lower Account first, so the loser waits holding nothing and
	 * there is no cycle to form.
	 *
	 * <p>A deadlock shows up here either as H2 refusing one of the two, which fails the
	 * "neither direction is refused" assertion, or as two threads that never return, which
	 * fails on {@link #BEFORE_GIVING_UP}.
	 */
	@Test
	@DisplayName("opposing Transfers between one pair of Accounts both complete")
	void opposingTransfersBetweenOnePairOfAccountsBothComplete() throws Exception {
		openAccount(LOWER_ID, 500_00L, EUR);
		openAccount(HIGHER_ID, 500_00L, EUR);

		List<Attempt> attempts = race(
				transferOf(100_00L, LOWER_ID, HIGHER_ID),
				transferOf(100_00L, HIGHER_ID, LOWER_ID));

		assertThat(attempts).allSatisfy(attempt ->
				assertThat(attempt.refusal()).as("neither direction is refused").isNull());

		assertThat(reservedAmountOf(LOWER_ID)).isEqualTo(100_00L);
		assertThat(reservedAmountOf(HIGHER_ID)).isEqualTo(100_00L);
		assertThat(balanceOf(LOWER_ID)).isEqualTo(500_00L);
		assertThat(balanceOf(HIGHER_ID)).isEqualTo(500_00L);
		assertThat(transferRows()).hasSize(2);
	}

	/**
	 * Runs both reservations on threads of their own, each held at its first row lock until
	 * the other has reached one, and reports what each of them got. Waiting on the futures
	 * with a timeout is what turns a deadlock from a suite that hangs into a test that fails.
	 */
	private List<Attempt> race(ReservationRequest first, ReservationRequest second) throws Exception {
		rowLocks.holdEachThreadAtItsFirstRowLock(2);
		ExecutorService threads = Executors.newFixedThreadPool(2);
		try {
			List<Future<Attempt>> attempts = Stream.of(first, second)
					.map(request -> threads.submit(() -> attempt(request)))
					.toList();

			List<Attempt> outcomes = new ArrayList<>();
			for (Future<Attempt> attempt : attempts) {
				outcomes.add(attempt.get(BEFORE_GIVING_UP.toSeconds(), TimeUnit.SECONDS));
			}
			return outcomes;
		}
		finally {
			rowLocks.release();
			threads.shutdownNow();
		}
	}

	private Attempt attempt(ReservationRequest request) {
		try {
			return new Attempt(reservation.reserve(request), null);
		}
		catch (RuntimeException refusal) {
			return new Attempt(null, refusal);
		}
	}

	/** What one thread came back with: a Transfer or the reason there is none. */
	private record Attempt(Transfer transfer, RuntimeException refusal) {

		boolean succeeded() {
			return refusal == null;
		}
	}
}

